package com.nextfeet.nextfeet.model; import java.math.BigDecimal; import java.time.LocalDateTime; public class Pedido { private Integer id,usuarioId,direccionId; private String codigo,estado,metodoPago,motivoAnulacion; private LocalDateTime fecha; private BigDecimal total; public Pedido(){} public Integer getId(){return id;} public void setId(Integer v){id=v;} public Integer getUsuarioId(){return usuarioId;} public void setUsuarioId(Integer v){usuarioId=v;} public Integer getDireccionId(){return direccionId;} public void setDireccionId(Integer v){direccionId=v;} public String getCodigo(){return codigo;} public void setCodigo(String v){codigo=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public String getMetodoPago(){return metodoPago;} public void setMetodoPago(String v){metodoPago=v;} public String getMotivoAnulacion(){return motivoAnulacion;} public void setMotivoAnulacion(String v){motivoAnulacion=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} }